import pandas as pd
def clean(df):
    df = df.copy()
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', '', regex=False), errors='coerce')
    df['sex'] = df['sex'].astype(str).str.strip()
    return df
def answer(df):
    df = clean(df)
    grouped = df.dropna(subset=['species', 'body_mass_g']).groupby('species')['body_mass_g'].sum()
    return {str(k): int(v) for k, v in grouped.items()}
